css:
.chargedsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8eef7;
    background: radial-gradient(circle at 18% 0%, #16233f 0%, #0c1426 55%, #070c18 100%);
    border-radius: 18px;
}

.chargedsim-container * {
    box-sizing: border-box;
}

.chargedsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0e2a52 0%, #123a6b 50%, #0b6f8c 100%);
    color: #f3f9ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 34px rgba(8, 20, 40, 0.55), inset 0 0 0 1px rgba(80, 220, 255, 0.18);
}

.chargedsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    text-shadow: 0 0 18px rgba(64, 224, 255, 0.45);
}

.chargedsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8ff0ff;
    background: rgba(64, 224, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(64, 224, 255, 0.25);
}

.chargedsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe3f5;
}

.chargedsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aecbe6;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.chargedsim-period-counter #currentDay,
.chargedsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #40e0ff;
}

.chargedsim-round-name {
    background: rgba(64, 224, 255, 0.14);
    color: #8ff0ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(64, 224, 255, 0.3);
}

.chargedsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 178, 44, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 178, 44, 0.3);
}

.chargedsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.chargedsim-status-card {
    background: linear-gradient(180deg, #14233f 0%, #101b32 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #243a5e;
    box-shadow: 0 6px 18px rgba(5, 12, 26, 0.5);
    border-top: 4px solid #40e0ff;
}

.chargedsim-card-energy { border-top-color: #40e0ff; }
.chargedsim-card-engage { border-top-color: #4fd08a; }
.chargedsim-card-burnout { border-top-color: #ff8a4f; }
.chargedsim-card-attrition { border-top-color: #c08bff; }

.chargedsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa3c2;
}

.chargedsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #e8eef7;
}

.chargedsim-card-energy .chargedsim-value { color: #40e0ff; text-shadow: 0 0 16px rgba(64, 224, 255, 0.4); }
.chargedsim-card-engage .chargedsim-value { color: #4fd08a; }
.chargedsim-card-burnout .chargedsim-value { color: #ff8a4f; }
.chargedsim-card-attrition .chargedsim-value { color: #c08bff; }

.chargedsim-sublabel {
    font-size: 0.74rem;
    color: #7e96b5;
    line-height: 1.35;
}

.chargedsim-energy-target .chargedsim-value { color: #4fd08a; text-shadow: 0 0 18px rgba(79, 208, 138, 0.5); }
.chargedsim-energy-fail .chargedsim-value { color: #ff6b6b; }

.chargedsim-burnout-high { border-top-color: #ff5252; }
.chargedsim-burnout-high .chargedsim-value { color: #ff5252; }
.chargedsim-attrition-high { border-top-color: #ff5252; }
.chargedsim-attrition-high .chargedsim-value { color: #ff5252; }

.chargedsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    background: linear-gradient(90deg, #0e2a52 0%, #0b6f8c 100%);
    color: #eaf7ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
    border: 1px solid rgba(64, 224, 255, 0.2);
}

.chargedsim-budget-bar #budgetDisplay,
.chargedsim-budget-bar #attentionDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #8ff0ff;
}

.chargedsim-attention {
    margin-left: auto;
    color: #cfe3f5;
}

.chargedsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(180deg, #14233f 0%, #101b32 100%);
    border-left: 5px solid #40e0ff;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(5, 12, 26, 0.4);
}

.chargedsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
    filter: drop-shadow(0 0 8px rgba(64, 224, 255, 0.6));
}

.chargedsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #8ff0ff;
    margin-bottom: 6px;
}

.chargedsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cfe0f2;
}

.chargedsim-briefing-text strong { color: #4fd08a; }
.chargedsim-briefing-text em { color: #ffd27a; font-style: italic; }

.chargedsim-controls {
    background: linear-gradient(180deg, #14233f 0%, #0f1a30 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #243a5e;
    box-shadow: 0 6px 18px rgba(5, 12, 26, 0.45);
}

.chargedsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #e8eef7;
    border-bottom: 2px solid #243a5e;
    padding-bottom: 8px;
}

.chargedsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #bcd2ec;
    margin: 14px 0 6px;
}

.chargedsim-container select,
.chargedsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f4a72;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0d1730;
    color: #e8eef7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.chargedsim-container select:focus,
.chargedsim-container input[type="number"]:focus {
    outline: none;
    border-color: #40e0ff;
    box-shadow: 0 0 0 3px rgba(64, 224, 255, 0.18);
}

.chargedsim-container select option {
    background-color: #0d1730;
    color: #e8eef7;
}

.chargedsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #40e0ff;
}

.chargedsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aecbe6;
    margin-top: 4px;
}

.chargedsim-range-readout span:last-child {
    color: #4fd08a;
    font-weight: 800;
}

.chargedsim-hint {
    font-size: 0.8rem;
    color: #8aa3c2;
    margin-top: 4px;
    line-height: 1.4;
}

.chargedsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.chargedsim-container .btn-primary {
    background: linear-gradient(135deg, #0b6f8c 0%, #40e0ff 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #06121f;
    box-shadow: 0 6px 18px rgba(64, 224, 255, 0.3);
}

.chargedsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.chargedsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2f4a72;
    color: #aecbe6;
    background: transparent;
}

.chargedsim-coach {
    background: linear-gradient(135deg, #102a52 0%, #0a1a36 100%);
    color: #e3eefb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(5, 12, 26, 0.5);
    border: 1px solid rgba(64, 224, 255, 0.18);
}

.chargedsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8ff0ff;
    margin-bottom: 8px;
}

.chargedsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.chargedsim-coach-body strong { color: #ffd27a; }
.chargedsim-coach-body em { color: #ff9d6e; font-style: italic; }

.chargedsim-history,
.chargedsim-chart {
    background: linear-gradient(180deg, #14233f 0%, #0f1a30 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #243a5e;
    box-shadow: 0 6px 18px rgba(5, 12, 26, 0.45);
}

.chargedsim-history h3,
.chargedsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #e8eef7;
}

.chargedsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cfe0f2;
}

.chargedsim-container table#usfHistoryTable th {
    background: #16294a;
    color: #8ff0ff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2f4a72;
}

.chargedsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1d2f4f;
}

.chargedsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(22, 41, 74, 0.45);
}

.chargedsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .chargedsim-container {
        padding: 14px;
    }
    .chargedsim-header h1 {
        font-size: 1.7rem;
    }
    .chargedsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .chargedsim-value {
        font-size: 2rem;
    }
    .chargedsim-clock {
        margin-left: 0;
    }
    .chargedsim-period-counter {
        font-size: 0.88rem;
    }
    .chargedsim-budget-bar {
        flex-direction: column;
        align-items: flex-start;
    }
    .chargedsim-attention {
        margin-left: 0;
    }
    .chargedsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, chargedsim) ---- */
.chargedsim-completion { padding: 8px 4px 4px; }
.chargedsim-cm-head { text-align: center; margin-bottom: 16px; }
.chargedsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.chargedsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.chargedsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.chargedsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.chargedsim-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.chargedsim-cm-no { background: rgba(192,86,31,0.12); color: #b0521f; border: 1px solid rgba(192,86,31,0.45); }
.chargedsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.chargedsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(42,74,122,0.08); border: 1px solid rgba(42,74,122,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.chargedsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2a4a7a; }
.chargedsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.chargedsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.chargedsim-cm-insights { margin: 0; padding-left: 20px; }
.chargedsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

