(function() {
    'use strict';

    class ChargedAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Fully Charged`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Northgate Platform Engineering).
            this.START_ENERGY = 38;        // productive-energy diagnostic /100
            this.TARGET_ENERGY = 60;       // board wants it visibly climbing past this
            this.START_ENGAGE = 54;        // down from 78%
            this.COMPANY_ENGAGE = 72;      // benchmark
            this.START_BURNOUT = 41;       // % high-exhaustion (company 19)
            this.COMPANY_BURNOUT = 19;
            this.START_ATTRITION = 18;     // % regretted attrition (company 9)
            this.COMPANY_ATTRITION = 9;
            this.BUDGET_CAP = 600;         // £600k, in thousands
            this.LEVER_CAP = 2;            // leadership attention funds ~2 levers

            // Concept truths.
            this.TRUE_STATE = `corrosive`;
            this.TRUE_TARGET = `productive`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    energy: this.START_ENERGY,
                    engage: this.START_ENGAGE,
                    burnout: this.START_BURNOUT,
                    attrition: this.START_ATTRITION,
                    budgetUsed: 0,
                    leversCommitted: 0,
                    accelerationTrap: false,
                    targetMissed: false,
                    energyHistory: [this.START_ENERGY],
                    engageHistory: [this.START_ENGAGE],
                    burnoutHistory: [this.START_BURNOUT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    state: `corrosive`,
                    intensity: `high`,
                    quality: `negative`,
                    rigor: 60,
                    target: `productive`,
                    strategy: `dragon`,
                    load: 0,
                    shortlist: 3,
                    lever1: `rebuild`,
                    lever2: `vision`,
                    sequence: `threatfirst`,
                    budget: 250,
                    deload: 60,
                    sustain: `embed`,
                    monitor: `both`,
                    board: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const st = document.getElementById(`stateInput`);
                const inten = document.getElementById(`intensityInput`);
                const qual = document.getElementById(`qualityInput`);
                const rig = document.getElementById(`rigorInput`);
                if (st) decisions.state = st.value;
                if (inten) decisions.intensity = inten.value;
                if (qual) decisions.quality = qual.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const tg = document.getElementById(`targetInput`);
                const str = document.getElementById(`strategyInput`);
                const ld = document.getElementById(`loadInput`);
                const sl = document.getElementById(`shortlistInput`);
                if (tg) decisions.target = tg.value;
                if (str) decisions.strategy = str.value;
                if (ld) decisions.load = parseInt(ld.value, 10);
                if (sl) decisions.shortlist = parseInt(sl.value, 10);
                if (!Number.isFinite(decisions.load) || decisions.load < -100 || decisions.load > 100) {
                    warn(`warn_load_range`); return false;
                }
                if (!Number.isFinite(decisions.shortlist) || decisions.shortlist < 1 || decisions.shortlist > 8) {
                    warn(`warn_shortlist_range`); return false;
                }
            } else if (round === 3) {
                const l1 = document.getElementById(`lever1Input`);
                const l2 = document.getElementById(`lever2Input`);
                const seq = document.getElementById(`sequenceInput`);
                const bg = document.getElementById(`budgetInput`);
                const dl = document.getElementById(`deloadInput`);
                if (l1) decisions.lever1 = l1.value;
                if (l2) decisions.lever2 = l2.value;
                if (seq) decisions.sequence = seq.value;
                if (bg) decisions.budget = parseFloat(bg.value);
                if (dl) decisions.deload = parseInt(dl.value, 10);
                if (decisions.lever1 === decisions.lever2) {
                    warn(`warn_levers_same`); return false;
                }
                if (!Number.isFinite(decisions.budget) || decisions.budget < 0 || decisions.budget > this.BUDGET_CAP) {
                    warn(`warn_budget_range`); return false;
                }
                if (!Number.isFinite(decisions.deload) || decisions.deload < 0 || decisions.deload > 100) {
                    warn(`warn_deload_range`); return false;
                }
            } else if (round === 4) {
                const su = document.getElementById(`sustainInput`);
                const mo = document.getElementById(`monitorInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (su) decisions.sustain = su.value;
                if (mo) decisions.monitor = mo.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // energyDelta = real productive energy; spikeDelta = adrenaline that masks burnout;
            // engageDelta = engagement %; burnoutDelta/attrDelta = risk (positive = worse).
            let energyDelta = 0, spikeDelta = 0, engageDelta = 0, burnoutDelta = 0, attrDelta = 0;
            let spend = 0, leversAdded = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the dominant state across BOTH axes (Common Error 1).
                if (d.state === this.TRUE_STATE) {
                    energyDelta += 14; engageDelta += 4; coachKey = `coach_r1_corrosive`;
                } else if (d.state === `burnout`) {
                    energyDelta -= 8; burnoutDelta += 2; coachKey = `coach_r1_burnout`;
                } else if (d.state === `resigned`) {
                    energyDelta -= 4; coachKey = `coach_r1_resigned`;
                } else {
                    energyDelta -= 10; engageDelta -= 2; coachKey = `coach_r1_comfortable`;
                }

                // The two axes: high intensity + negative quality define corrosive energy.
                const axesRight = (d.intensity === `high` && d.quality === `negative`);
                if (axesRight) {
                    energyDelta += 10; engageDelta += 3;
                    if (d.state === this.TRUE_STATE) coachKey = `coach_r1_sharp`;
                } else if (d.quality === `positive`) {
                    // Misreading the quality as positive is the central trap.
                    energyDelta -= 8; coachKey = `coach_r1_quality`;
                } else {
                    energyDelta -= 3;
                }

                // Diagnostic rigor: reading quality, not just hours.
                if (d.rigor >= 60) { energyDelta += 6; }
                else if (d.rigor <= 25) { energyDelta -= 6; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.state === this.TRUE_STATE && axesRight) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set destination + shortlist (Common Errors 3 & 4).
                switch (d.target) {
                    case `productive`: energyDelta += 10; engageDelta += 4; coachKey = `coach_r2_productive`; break;
                    case `comfortable`: energyDelta += 2; engageDelta += 2; coachKey = `coach_r2_comfortable`; break;
                    case `harder`: energyDelta -= 8; burnoutDelta += 6; coachKey = `coach_r2_harder`; break;
                }

                // Mobilising strategy: when energy is corrosive, slay the dragon FIRST.
                switch (d.strategy) {
                    case `dragon`: energyDelta += 8; engageDelta += 3; coachKey = (d.target === `productive`) ? `coach_r2_dragon` : coachKey; break;
                    case `princess`: energyDelta -= 6; engageDelta -= 4; spikeDelta += 4; coachKey = `coach_r2_princess`; break;
                    case `both`: energyDelta -= 4; spikeDelta += 6; burnoutDelta += 4; coachKey = `coach_r2_both`; break;
                }

                // Acceleration-trap check: de-loading (negative) helps; adding load spikes then burns.
                if (d.load <= -30) { energyDelta += 8; burnoutDelta -= 6; coachKey = (d.strategy === `dragon`) ? `coach_r2_deload` : coachKey; }
                else if (d.load >= 30) { spikeDelta += 8; burnoutDelta += 8; attrDelta += 2; coachKey = `coach_r2_addload`; }

                // Focus: leadership attention is the scarcest resource. Two beats five.
                if (d.shortlist === 2) { energyDelta += 8; engageDelta += 3; }
                else if (d.shortlist === 1 || d.shortlist === 3) { energyDelta += 2; }
                else if (d.shortlist >= 5) { energyDelta -= 8; engageDelta -= 4; coachKey = `coach_r2_spread`; }

                summaryKey = (d.target === `productive` && d.strategy === `dragon` && d.load <= -10 && d.shortlist <= 3) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Sequence & commit exactly two levers (Common Errors 2, 3 & 5).
                leversAdded = 2;
                const levers = [d.lever1, d.lever2];
                const has = (k) => levers.indexOf(k) !== -1;

                // Per-lever cost & primary effect.
                const cost = { rebuild: 60, delayer: 40, coaching: 80, vision: 60, hire: 190, perks: 20, reorg: 120 };
                let leverEnergy = 0, leverEngage = 0, leverBurnout = 0, leverAttr = 0;
                levers.forEach((lv) => {
                    spend += (cost[lv] || 0);
                    switch (lv) {
                        case `delayer`: leverEnergy += 11; leverEngage += 5; leverBurnout -= 8; leverAttr -= 2; break;   // restores autonomy, cuts the load — the core fix
                        case `rebuild`: leverEnergy += 10; leverEngage += 4; leverAttr -= 4; break;                       // resolves the post-merger politics (the dragon)
                        case `vision`: leverEnergy += 6; leverEngage += 5; break;                                          // the princess — powerful AFTER stabilisation
                        case `coaching`: leverEnergy += 5; leverEngage += 2; break;                                        // helps leaders model the new energy
                        case `hire`: leverEnergy += 4; leverBurnout -= 5; leverAttr -= 2; break;                          // relieves load but expensive & slow
                        case `perks`: leverEnergy -= 4; leverBurnout -= 1; break;                                          // a £20k apology on top of corrosive energy
                        case `reorg`: leverEnergy -= 8; leverEngage -= 5; leverBurnout += 3; break;                       // the very move that created the corrosion
                    }
                });
                energyDelta += leverEnergy; engageDelta += leverEngage; burnoutDelta += leverBurnout; attrDelta += leverAttr;

                if (has(`perks`)) coachKey = `coach_r3_perks`;
                if (has(`reorg`)) coachKey = `coach_r3_reorg`;

                // A relational/motivational lever must sit alongside structure (Common Error 5).
                const relational = has(`rebuild`) || has(`vision`) || has(`coaching`);
                if (!relational) { energyDelta -= 6; coachKey = `coach_r3_structureonly`; }

                // Sequencing: dragon (stabilise threat/friction) before princess (vision).
                if (d.sequence === `threatfirst`) {
                    energyDelta += 8; engageDelta += 3;
                    // The classic right move: stabilise first (lever1) then mobilise vision (lever2).
                    if (d.lever1 !== `vision` && d.lever2 === `vision`) { energyDelta += 6; coachKey = `coach_r3_sequenced`; }
                    else { coachKey = (coachKey === `coach_default`) ? `coach_r3_threatfirst` : coachKey; }
                } else if (d.sequence === `visionfirst`) {
                    energyDelta -= 8; engageDelta -= 5; spikeDelta += 5; coachKey = `coach_r3_visionfirst`;
                } else {
                    energyDelta -= 4; spikeDelta += 4; coachKey = `coach_r3_parallel`;
                }
                // Launching the vision lever literally first while politics rage backfires.
                if (d.lever1 === `vision`) { energyDelta -= 6; engageDelta -= 4; spikeDelta += 4; coachKey = `coach_r3_visionlever`; }

                // Funding conviction: under-funding reads as flavour-of-the-month; a healthy band lands.
                spend = Math.min(spend, d.budget);
                if (d.budget >= 250 && d.budget <= 450) { energyDelta += 6; engageDelta += 2; }
                else if (d.budget < 150) { energyDelta -= 6; coachKey = `coach_r3_underfund`; }
                else if (d.budget > 520) { energyDelta -= 2; }

                // Protecting the de-load when the mid-quarter shock hits.
                if (d.deload >= 60) { energyDelta += 6; burnoutDelta -= 6; attrDelta -= 1; }
                else if (d.deload <= 25) { spikeDelta += 6; burnoutDelta += 6; coachKey = `coach_r3_nodeload`; }

                const goodLevers = (has(`delayer`) || has(`rebuild`)) && !has(`perks`) && !has(`reorg`);
                summaryKey = (goodLevers && d.sequence === `threatfirst`) ? `sum_r3_good` :
                    ((has(`perks`) || has(`reorg`) || d.sequence === `visionfirst`) ? `sum_r3_trap` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover, measure & defend (Common Error 4 + acceleration trap).
                switch (d.sustain) {
                    case `embed`: energyDelta += 10; engageDelta += 4; burnoutDelta -= 6; attrDelta -= 3; coachKey = `coach_r4_embed`; break;
                    case `rally`: spikeDelta += 8; burnoutDelta += 6; attrDelta += 2; coachKey = `coach_r4_rally`; break;
                    case `overtime`: energyDelta -= 6; burnoutDelta += 10; attrDelta += 4; coachKey = `coach_r4_overtime`; break;
                }

                // Monitoring for the acceleration trap.
                switch (d.monitor) {
                    case `both`: energyDelta += 6; burnoutDelta -= 4; coachKey = (d.sustain === `embed`) ? `coach_r4_monitor` : coachKey; break;
                    case `energyonly`: spikeDelta += 4; coachKey = `coach_r4_energyonly`; break;
                    case `none`: spikeDelta += 6; burnoutDelta += 4; coachKey = `coach_r4_nomonitor`; break;
                }

                // Defending to the board.
                switch (d.board) {
                    case `honest`: energyDelta += 8; engageDelta += 3; coachKey = (d.sustain === `embed`) ? `coach_r4_honest` : coachKey; break;
                    case `spin`: spikeDelta += 8; burnoutDelta += 4; attrDelta += 2; coachKey = `coach_r4_spin`; break;
                    case `defer`: energyDelta -= 8; attrDelta += 4; coachKey = `coach_r4_defer`; break;
                }

                // Conviction nudge.
                energyDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.sustain === `embed` && d.monitor === `both` && d.board === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));
            ds.leversCommitted = ds.leversCommitted + leversAdded;

            // Scale the raw deltas so the 0–100 meters keep headroom through all four rounds:
            // a flawless run lands in the low 80s (not pegged early), and a late wrong lever
            // still leaves a visible mark. Wrong strategies stay measurably below the target.
            const realDelta = energyDelta * 0.42;                  // real productive-energy move
            const spikeLift = Math.max(0, spikeDelta) * 0.32;      // temporary adrenaline bump
            ds.energy = Math.max(0, Math.min(100, ds.energy + realDelta + spikeLift));

            // Engagement.
            ds.engage = Math.max(0, Math.min(100, ds.engage + engageDelta * 0.6 - Math.max(0, spikeDelta) * 0.3));

            // Burnout risk (lower is better). Spike always worsens it.
            const burnoutMove = burnoutDelta * 0.7 + Math.max(0, spikeDelta) * 0.6;
            ds.burnout = Math.max(0, Math.min(100, ds.burnout + burnoutMove));

            // Regretted attrition (lower is better). Worsens with burnout, eases as energy recovers.
            attrDelta += Math.max(0, spikeDelta) * 0.15 - Math.max(0, realDelta) * 0.08;
            ds.attrition = Math.max(0, Math.min(40, Math.round((ds.attrition + attrDelta) * 10) / 10));

            // Acceleration trap: energy looks up while burnout is climbing too.
            if (Math.max(0, spikeDelta) >= 6 && burnoutMove > 1.5) ds.accelerationTrap = true;

            ds.energyHistory.push(Math.round(ds.energy));
            ds.engageHistory.push(Math.round(ds.engage));
            ds.burnoutHistory.push(Math.round(ds.burnout));

            if (round === this.ROUNDS.length && ds.energy < this.TARGET_ENERGY) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                energy: Math.round(ds.energy),
                energyDelta: Math.round(realDelta + spikeLift),
                engage: Math.round(ds.engage),
                burnout: Math.round(ds.burnout),
                attrition: Math.round(ds.attrition * 10) / 10,
                budgetUsed: ds.budgetUsed,
                leversCommitted: ds.leversCommitted,
                accelerationTrap: ds.accelerationTrap,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

