        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const energy = Math.round(ds.energy);
            const engage = Math.round(ds.engage);
            const burnout = Math.round(ds.burnout);
            const attrition = Math.round(ds.attrition * 10) / 10;
            const burnoutScore = Math.max(0, 100 - (burnout - this.COMPANY_BURNOUT) * 2.2);
            const attrScore = Math.max(0, 100 - (attrition - this.COMPANY_ATTRITION) * 7);
            const composite = Math.min(100, Math.round(energy * 0.34 + engage * 0.26 + burnoutScore * 0.22 + attrScore * 0.18));
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitTarget && s.sustainable);
            const badge = met
                ? `<span class="chargedsim-cm-badge chargedsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="chargedsim-cm-badge chargedsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = s.trap
                ? ` <span class="chargedsim-cm-badge chargedsim-cm-no">` + T(`cm_trap`) + `</span>`
                : (s.targetMissed ? ` <span class="chargedsim-cm-badge chargedsim-cm-no">` + T(`cm_missed`) + `</span>` : ``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const attrStr = (typeof s.attrition === `number`) ? s.attrition + `%` : String(s.attrition || ``);
            const metrics = ``
                + `<div class="chargedsim-cm-metric"><span class="chargedsim-cm-mv">` + Math.round(s.energy || 0) + `</span><span class="chargedsim-cm-ml">` + T(`cm_m_energy`) + `</span></div>`
                + `<div class="chargedsim-cm-metric"><span class="chargedsim-cm-mv">` + Math.round(s.engage || 0) + `%</span><span class="chargedsim-cm-ml">` + T(`cm_m_engage`) + `</span></div>`
                + `<div class="chargedsim-cm-metric"><span class="chargedsim-cm-mv">` + Math.round(s.burnout || 0) + `</span><span class="chargedsim-cm-ml">` + T(`cm_m_burnout`) + `</span></div>`
                + `<div class="chargedsim-cm-metric"><span class="chargedsim-cm-mv">` + attrStr + `</span><span class="chargedsim-cm-ml">` + T(`cm_m_attrition`) + `</span></div>`;
            return ``
                + `<div class="chargedsim-completion">`
                +   `<div class="chargedsim-cm-head">`
                +     `<div class="chargedsim-cm-score">` + score + `<span class="chargedsim-cm-score-max">/100</span></div>`
                +     `<div class="chargedsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="chargedsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="chargedsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="chargedsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const energy = Math.round(ds.energy);
            const engage = Math.round(ds.engage);
            const burnout = Math.round(ds.burnout);
            const attrition = Math.round(ds.attrition * 10) / 10;

            const hitTarget = energy >= this.TARGET_ENERGY;
            const sustainable = burnout <= 28 && attrition <= 14;
            const trap = ds.accelerationTrap || (hitTarget && burnout >= 38);
            // Composite: energy + engagement headroom + reduced burnout + reduced attrition.
            const burnoutScore = Math.max(0, 100 - (burnout - this.COMPANY_BURNOUT) * 2.2);
            const attrScore = Math.max(0, 100 - (attrition - this.COMPANY_ATTRITION) * 7);
            const composite = Math.min(100, Math.round(energy * 0.34 + engage * 0.26 + burnoutScore * 0.22 + attrScore * 0.18));

            let performanceKey = `grade_restructured`;
            if (hitTarget && sustainable && composite >= 72) performanceKey = `grade_recharged`;
            else if (hitTarget && sustainable) performanceKey = `grade_credible`;
            else if (hitTarget && trap) performanceKey = `grade_trap`;
            else if (hitTarget) performanceKey = `grade_fragile`;
            else if (energy > this.START_ENERGY + 10) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && sustainable) insights.push(window.mySimulation.t(`insight_recharged`));
            else if (hitTarget && trap) insights.push(window.mySimulation.t(`insight_trap`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (burnout >= 38) insights.push(window.mySimulation.t(`insight_burnout`));
            if (attrition >= 15) insights.push(window.mySimulation.t(`insight_attrition`));
            if (engage >= this.COMPANY_ENGAGE) insights.push(window.mySimulation.t(`insight_engage`));
            if (hitTarget && sustainable && burnout <= 24) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                energy: energy,
                engage: engage,
                burnout: burnout,
                attrition: attrition,
                hitTarget: hitTarget,
                sustainable: sustainable,
                trap: trap,
                targetMissed: ds.targetMissed,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.accelerationTrap) return window.mySimulation.t(`hint_trap`);
            if (ds.burnout >= 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_burnout`);
            if (ds.energy < 35) return window.mySimulation.t(`hint_energy`);
            if (state.currentPeriod >= 3 && ds.energy < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.energy >= this.TARGET_ENERGY && ds.burnout <= 28 && ds.attrition <= 14) return window.mySimulation.t(`hint_strong`);
            return null;
        }

